#!/usr/bin/env node

/**
 * Checks that a docs-sync PR body is markdown that renders on GitHub the way it
 * reads: LF line endings, real newlines, a blank line between blocks, no
 * hard-wrapped paragraphs, closed code spans, code blocks, bold, and links, and
 * no raw HTML or unfilled <placeholders>. It also checks that the "Generated by
 * Claude" disclaimer is the first line and the only attribution, and that there
 * are no icons. Template content and wording are left to the prompt in
 * .github/prompts/docs-sync.md.
 *
 * Usage:
 *   node .github/scripts/check-pr-body.mjs --body-file <path>
 *   node .github/scripts/check-pr-body.mjs --pr <number> [--repo owner/name]
 *
 * Exit codes: 0 prints "OK", 1 lists each problem, 2 means the body could not be
 * read (bad arguments, or gh failed).
 */

import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { parseArgs } from 'node:util';

const DISCLAIMER = '> _Generated by Claude. Review carefully before merging._';
// Emoji, pictographs, dingbats, check marks, stars, shapes, flags, and the emoji
// variation selector. (C), (R) and TM signs are text, so they're allowed.
const ICON_RE = /(?![\u00A9\u00AE\u2122])[\p{Extended_Pictographic}\u2022\u25A0-\u25FF\u2600-\u27BF\u2B00-\u2BFF\u{1F1E6}-\u{1F1FF}\uFE0F]/u;
const SHORTCODE_RE = /(^|[\s(]):[a-z][a-z0-9_+-]*:(?=$|[\s).,;!?])/;
// Characters that look like a space or nothing but aren't one to GitHub.
const INVISIBLE_RE = /[\u00A0\u2028\u2029\u200B-\u200D\u2060\uFEFF\u3000]/;
// Credits to Claude or an AI, as a footer line or a sentence about this PR. The
// disclaimer on line 1 is the only one allowed. Docs content that mentions
// Claude Code mid-sentence doesn't match.
const AI = String.raw`(the |anthropic'?s )?[\[*_]*(claude|an? (ai|llm|bot|agent)\b)`;
const CREDIT = String.raw`(generated|written|created|authored|made|drafted|produced|opened)( automatically)? (by|with|using|via) ${AI}`;
const ATTRIBUTION_RE = new RegExp(
  String.raw`^\W*${CREDIT}|\b(this|the) (pr|pull request|description)\b[^.]*\b${CREDIT}|\bclaude[- ]generated\b|^co-authored-by:`,
  'i',
);
const FENCE_RE = /^( {0,3})(`{3,}|~{3,})(.*)$/;
const TABLE_DELIMITER_RE = /^\|(\s*:?-+:?\s*\|)+\s*$/;

const { values } = parseArgs({
  options: {
    'body-file': { type: 'string' },
    pr: { type: 'string' },
    repo: { type: 'string', default: 'powersync-ja/agent-skills' },
  },
});

let body;
try {
  if (values.pr) {
    body = execFileSync('gh', ['pr', 'view', values.pr, '--repo', values.repo, '--json', 'body', '--jq', '.body'], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
  } else if (values['body-file']) {
    body = readFileSync(values['body-file'], 'utf8');
  } else {
    console.error('Usage: check-pr-body.mjs --body-file <path> | --pr <number> [--repo owner/name]');
    process.exit(2);
  }
} catch (e) {
  console.error(`Could not read the PR body: ${e.message.split('\n')[0]}`);
  process.exit(2);
}

const problems = [];
const problem = (line, msg) => problems.push(line ? `line ${line}: ${msg}` : msg);

// Splits a line the way CommonMark does: a run of N backticks opens a code span
// that closes at the next run of exactly N, and outside code a backslash escapes
// the next character. Returns the line with code spans removed, and whether a
// backtick run was left open.
function scanCode(text) {
  let prose = '';
  let unclosed = false;
  let i = 0;
  while (i < text.length) {
    if (text[i] === '\\' && i + 1 < text.length) {
      prose += text.slice(i, i + 2);
      i += 2;
      continue;
    }
    if (text[i] !== '`') {
      prose += text[i++];
      continue;
    }
    let j = i;
    while (text[j] === '`') j++;
    const run = j - i;
    let close = -1;
    for (let k = j; k < text.length; ) {
      if (text[k] !== '`') {
        k++;
        continue;
      }
      let m = k;
      while (text[m] === '`') m++;
      if (m - k === run) {
        close = k;
        break;
      }
      k = m;
    }
    if (close === -1) {
      unclosed = true;
      prose += text.slice(i, j);
      i = j;
    } else {
      i = close + run;
    }
  }
  return { prose, unclosed };
}

const isBlank = (l) => /^[ \t]*$/.test(l);
const isHeading = (l) => /^#{1,6}([ \t]|$)/.test(l);
const isItem = (l) => /^ *(- |\d+[.)] )/.test(l);
const isQuote = (l) => /^>/.test(l);
const isTableRow = (l) => /^\|/.test(l);
const isLinkDefinition = (l) => /^\[[^\]]+\]:\s/.test(l);

if (!body.trim()) {
  problem(null, 'body is empty');
  report();
}
if (body.includes('\r')) problem(null, 'body has CR characters (CRLF line endings), use LF only');

const lines = body.replace(/\r/g, '').replace(/\n+$/, '').split('\n');

if (lines[0] !== DISCLAIMER) problem(1, `first line must be exactly: ${DISCLAIMER}`);

let fence = null; // { ch, len, line } while inside a fenced code block
let prevWasFence = false;
let seenHeading = false;

lines.forEach((text, i) => {
  const n = i + 1;
  const prev = i > 0 ? lines[i - 1] : '';
  const fm = FENCE_RE.exec(text);

  // A fence closes only on the same character, at least as long, with no info string.
  if (fence) {
    if (fm && fm[2][0] === fence.ch && fm[2].length >= fence.len && !fm[3].trim()) {
      fence = null;
      prevWasFence = true;
    }
    return;
  }
  if (fm && !(fm[2][0] === '`' && fm[3].includes('`'))) {
    if (!seenHeading) problem(n, 'code block before the first heading, is the body wrapped in a code block?');
    fence = { ch: fm[2][0], len: fm[2].length, line: n };
    return;
  }

  const { prose, unclosed } = scanCode(text);
  // Escaped characters are literal, and URLs are autolinked as they are.
  const plain = prose.replace(/\\./g, '').replace(/https?:\/\/\S+/g, '');

  if (INVISIBLE_RE.test(text)) problem(n, 'non-breaking or zero-width space, use a normal space or a truly blank line');
  if (text.includes('\t')) problem(n, 'tab character outside a code block, use spaces');
  if (/\\[nr]|\\u[0-9a-fA-F]{4}/.test(prose)) problem(n, 'literal "\\n" or "\\u" escape in text, write the real character instead');
  if (/[ \t]+$/.test(text)) problem(n, 'trailing whitespace (two trailing spaces force a hard line break)');
  if (/^ +\S/.test(text) && !(isItem(text) && isItem(prev))) {
    problem(n, /^ {4}/.test(text) ? 'indented 4+ spaces, GitHub renders it as a code block' : 'line starts with spaces, remove the indent');
  }
  if (/^(\*|\+) /.test(text)) problem(n, 'list item must start with "- "');
  if (/^-[A-Za-z`]/.test(text)) problem(n, 'list marker needs a space after it ("- ")');
  if (/^#{2,6}[^#\s]|^#[A-Za-z]{2,}/.test(text)) problem(n, 'heading needs a space after the # characters');
  if (unclosed) problem(n, 'unclosed inline code, a backtick is missing its pair');
  if ((plain.match(/\*\*/g) || []).length % 2) problem(n, 'unclosed bold, a ** is missing its pair');
  if ((plain.replace(/\*\*/g, '').match(/\*/g) || []).length >= 2 || /(^|[^\w])__\w+__(?!\w)/.test(plain)) {
    problem(n, 'stray * or __ outside code turns text italic or bold, put globs and code in backticks');
  }
  if ((plain.match(/~/g) || []).length >= 2) problem(n, 'a pair of ~ renders as strikethrough, write "about" or put it in backticks');
  if (/\]\([^)\s]*$/.test(prose)) problem(n, 'link is missing its closing )');
  if (/&#[xX]?[0-9a-fA-F]+;/.test(plain)) problem(n, 'HTML entity, write the plain character instead');
  if (/<!--|<\/?[A-Za-z][\w-]*(\s[^<>]*)?\/?>/.test(plain)) {
    problem(n, 'raw HTML or <text> outside backticks, GitHub hides it (an unfilled <placeholder> or a type like List<T>)');
  }
  if (/claude\.ai\/code\/\S|agent-skills\/actions\/runs\//i.test(text)) problem(n, 'session or workflow run link, remove it');
  if (n !== 1 && ATTRIBUTION_RE.test(prose)) problem(n, 'extra AI attribution, the disclaimer on line 1 is the only one allowed');
  if (ICON_RE.test(prose) || SHORTCODE_RE.test(plain)) problem(n, 'icon, emoji, or emoji shortcode, use plain text');
  if (isTableRow(text) && !isTableRow(prev) && !TABLE_DELIMITER_RE.test(lines[i + 1] ?? '')) {
    problem(n, 'table is missing its | --- | delimiter row, so GitHub shows it as plain text');
  }

  if (isHeading(text)) {
    seenHeading = true;
    if (i > 0 && !isBlank(prev)) problem(n, 'heading needs a blank line before it');
    if (i + 1 < lines.length && !isBlank(lines[i + 1])) problem(n, 'heading needs a blank line after it');
  } else if (n === 2 && !isBlank(text)) {
    problem(n, 'leave line 2 blank, or the next line joins the disclaimer quote');
  } else if (!isBlank(text) && !isBlank(prev) && !prevWasFence && !isHeading(prev)) {
    // In a PR body GitHub shows every single newline as a line break, so a
    // hard-wrapped paragraph renders as ragged short lines, and a line after a
    // quote or list item is pulled into it. Lines of one list, quote, or table
    // are fine together.
    const sameBlock =
      (isItem(text) && isItem(prev)) ||
      (isQuote(text) && isQuote(prev)) ||
      (isTableRow(text) && isTableRow(prev)) ||
      (isLinkDefinition(text) && isLinkDefinition(prev));
    if (!sameBlock) problem(n, 'needs a blank line before it, or join it to the previous line (no hard wraps)');
  }
  prevWasFence = false;
});

if (fence) problem(fence.line, 'code fence is never closed');

report();

function report() {
  if (problems.length) {
    console.error(`✗ ${problems.length} problem(s) in PR ${values.pr ? `#${values.pr}` : 'draft'}:`);
    for (const p of problems) console.error(`  - ${p}`);
    process.exit(1);
  }
  console.log('OK');
  process.exit(0);
}
